function nav(){document.querySelector('.profile').textContent=state.role==='student'?'HS':state.role==='parent'?'PH':'GV';document.querySelector('.bottom').innerHTML=menus[state.role].map(([i,l,p])=>`<button class="${state.page===p?'active':''}" onclick="go('${p}')">${icons[i]}<span>${l}</span></button>`).join('')}
function go(p){state.page=p;state.answered=false;render();scrollTo(0,0)}
function render(){nav();const f=views[state.page]||views.home;document.querySelector('#view').innerHTML=f();ensurePodcastWidget();ensureAiWidget();syncFloatingCharacters()}
